def f(x, y=10):
    return x + y
print(f(5))

def countdown(n):
    if n == 0:
        return 'Go!'
    return str(n) + ' ' + countdown(n - 1)
print(countdown(3))

def outer():
    x = 10
    def inner():
        print(x)
    inner()
outer()

def fact(n):
    if n <= 1:
        return 1
    return n * fact(n - 1)
print(fact(4))

def greet(name, msg='Hello'):
    print(f'{msg}, {name}!')
greet(msg='Hi', name='Alex')
